# -*- coding: utf-8 -*-
import sys; sys.path.insert(0, "Tools/prd_ledger/research_quit_habit")
from _lib import c, save

c(1, "header; intro lines 1-8", "data-caveat", "Research document, not a review corpus: a decision memo answering 'should quit-habits be a feature or a separate app?'. Its evidence base is 56,653 reviews of the category's #1 app (Habit Tracker), 10,621 reviews of the leading quit tracker (Days Since), and App Store search and ratings-count results across the standalone quit and vertical-sobriety markets. Public US ratings counts are the unit throughout, not downloads or revenue; no review IDs are cited, so every number resolves to a ratings count or a share-of-corpus figure rather than to an individual review. Headline recommendation stated up front: 'build it as a feature. Do not ship a generic quit tracker app.'", "n/a", "mixed", "56,653 + 10,621 reviews behind it; App Store ratings counts as the market unit; no review IDs", "none", "method", "generalisable", [], "", "market-structure evidence, so it ranks category positions rather than user sentiment")

c(2, "§1; §1 table (verbatim)", "market", "The generic 'quit anything' market has one incumbent and a graveyard behind it. US ratings (verbatim): App | US ratings ; Days Since: Quit Habit Tracker | 19,073 ; Quitzilla: Quit Tracker | 1,473 ; Quit Bad Habits & Addiction | 1,061 ; Days Without: Break Bad Habits | 6 ; ZeroBadHabits | 0 — 'One app has traction. The rest are near zero. That is not a market with room in it.' The ceiling on the category leader is ~19k US ratings.", "n/a", "mixed", "Days Since 19,073; Quitzilla 1,473; Quit Bad Habits 1,061; Days Without 6; ZeroBadHabits 0", "dont", "high-priority", "generalisable", [], "", "applies to a generic quit tracker, not to a vertical one")

c(3, "§2; §2 table (verbatim)", "market", "The money in quitting is in verticals, not in 'quit anything'. US ratings (verbatim): App | US ratings ; I Am Sober | 186,328 ; Smoke Free | 57,263 ; Reframe: Drink Less | 44,339 ; Sober Time | 41,632 ; Nomo — Sobriety Clocks | 16,398 ; QuitNow! | 13,572 — 'These beat every generic quit app by 3-10x.' The stated reason is search intent plus content: someone quitting smoking searches 'quit smoking', not 'quit tracker', and wants lung-recovery milestones, craving support and a community, 'none of which a generic counter provides'. The conclusion is that a generic quit app loses on both sides — too vague for the vertical searcher and redundant for the habit-tracker user.", "n/a", "mixed", "I Am Sober 186,328; Smoke Free 57,263; Reframe 44,339; Sober Time 41,632; Nomo 16,398; QuitNow! 13,572 — 3-10x the generic apps", "dont", "high-priority", "generalisable", [], "vertical apps own the high-intent keywords and the recovery content", "the vertical advantage rests on milestone content and community, not on the counter")

c(4, "§3", "positioning", "Quit tracking is becoming table stakes inside habit trackers rather than a differentiator: 8 of the top 40 habit trackers explicitly market breaking bad habits — including Habit Tracker (#1), HabitKit, Streaks and Simple Streak — and 'the #1 app already ships a Quit tab'. The document states both halves plainly: 'Shipping it doesn't differentiate you. Not shipping it is starting to look like a gap.'", "n/a", "mixed", "8 of the top 40 habit trackers market quitting; the #1 app ships a Quit tab", "must-have", "high-priority", "generalisable", [], "", "quit as a habit type is defensive parity; the differentiation has to come from doing it well, not from having it")

c(5, "§4", "insight", "Silence in the review corpus is not absence of demand when the leader already ships the feature: of 56,653 reviews of the #1 app only 164 (0.29%) mention quitting, but reading them they are 'overwhelmingly complaints about the existing quit feature, not requests for one'. The document treats the low count as evidence of a satisfied-then-disappointed surface rather than a dead one — a general rule for reading any request count against a feature that already exists.", "n/a", "complaint", "164 of 56,653 reviews (0.29%) mention quitting; the majority of those are complaints about the shipped feature", "product-rule", "high-priority", "generalisable", [], "", "holds when the incumbent ships the feature; a 0.29% count for a feature nobody ships means something different")

c(6, "§4 quotes (verbatim)", "anti-pattern", "The #1 app's quit implementation fails in five named ways, quoted from its reviews: 'the streak counter is sometimes wrong for Quit habits'; 'It is not possible to track if you want to quit drinking alcohol. You can only choose a max period of 1 month with a 2 drink minimum?'; \"When habits are set to 'Quit' with 0 per day — nothing is readable because of the all dark colors\"; 'I click the QUIT habit tab, I get the form error'; 'Bad for quitting habits'. The document names this as the opportunity: 'The leader ships quit-habits badly. Doing it properly is a differentiator inside your existing app — and costs you nothing in downloads, because the traffic is already coming for habit tracking.'", "leader: wrong streak count on quit habits, 1-month/2-drink allowance ceiling, unreadable dark mode, form error on the Quit tab", "complaint", "five distinct defects quoted from the #1 app's 56,653-review corpus", "do", "high-priority", "generalisable", [], "no incremental download cost — the traffic already arrives for habit tracking", "a differentiator only if the implementation is correct; shipping the same defects gains nothing")

c(7, "§5", "audience", "The quit audience and the build-good-habits audience barely overlap: only 2.4% of Days Since reviewers ask for good-habit building, and 'Quit users mostly want one thing: a clean day counter that does not reset.' The document says this cuts both ways — a combined app will not cannibalise a quit app, but a separate quit app gains almost no cross-sell: 'Two apps, two ASO efforts, two support queues, for two groups that don't migrate.'", "n/a", "mixed", "2.4% of Days Since reviewers ask for good-habit building", "dont", "high-priority", "generalisable", [], "low overlap removes the cannibalisation risk and the cross-sell case at the same time", "measured on the Days Since corpus (10,621 reviews)")

c(8, "§6; §6 table (verbatim)", "market", "What people actually quit, from 10,621 Days Since reviews (verbatim): Category | Share of reviews ; Alcohol | 5.0% ; Smoking / vaping | 3.7% ; Social media / phone | 2.0% ; Sugar / junk food | 1.0% ; Weed / drugs | 0.7% ; Nail biting, caffeine, gambling | 0.6% ; Porn | 0.2%. The two largest categories are locked up by the verticals; social media and phone use are not — 'no large dedicated app owns it, and it's the third-biggest quit reason. That's the one quit niche with genuine room.'", "n/a", "mixed", "alcohol 5.0%, smoking/vaping 3.7%, social media/phone 2.0%, sugar 1.0%, weed/drugs 0.7%, nail biting/caffeine/gambling 0.6%, porn 0.2% of 10,621 reviews", "research", "high-priority", "generalisable", [], "phone/social-media quitting is the unclaimed vertical", "shares are of all reviews, not of quit-intent reviews only")

c(9, "What to do, item 1", "feature", "A quit habit needs a days-since counter, not a streak: 'Quitting is days clean, not did it today.' The two mechanics are different data models and the document names the counter as the first-class requirement for the habit type.", "specified as a build requirement", "request", "document gives no count for this item", "must-have", "high-priority", "generalisable", [], "", "applies to the quit habit type only; good-habit tracking keeps the streak")

c(10, "What to do, item 2", "must-never-break", "A relapse must not wipe history — 'the most-repeated complaint in the Days Since corpus' (10,621 reviews). The specified behaviour is to log the slip, keep the record, and show best-ever alongside current. This is the single most-repeated item in the leading quit tracker's corpus, so it is the defining failure mode of the category.", "leading quit tracker: relapse destroys the record", "complaint", "the most-repeated complaint across 10,621 Days Since reviews", "must-never-break", "high-priority", "generalisable", [], "", "")

c(11, "What to do, item 3", "feature", "Quit goals need allowances, not only zero: \"'2 drinks a week' is a real goal; the leader caps at one month and users complain loudly about it.\" The #1 app's ceiling of a one-month maximum period with a two-drink minimum is quoted in §4 as a blocking limitation for alcohol tracking.", "leader: max period 1 month, 2-drink minimum, no open-ended allowance", "complaint", "document gives no count; the leader's limit is quoted verbatim from its reviews", "must-have", "high-priority", "generalisable", [], "", "moderation goals are a distinct mode from abstinence goals")

c(12, "What to do, item 4", "feature", "Milestones carry the emotional payload of a quit tracker: 1/7/30/90 days plus money saved, and \"Days Since's happiest reviews (4.77 average) are milestone screenshots\" — the highest-rated behaviour in the leading quit corpus is a user photographing a milestone, which makes the milestone screen both the retention moment and the sharing surface.", "leading quit tracker: milestones present and they are its best-rated moment", "praise", "milestone-screenshot reviews average 4.77★ in the 10,621-review Days Since corpus", "must-have", "high-priority", "generalisable", [], "the milestone screen doubles as the organic-sharing surface", "")

c(13, "What to do, item 5", "must-never-break", "Quit mode must be readable in dark mode — 'a literal, fixable complaint about the #1 app', whose quit habits set to 0 per day render as 'nothing is readable because of the all dark colors'. A contrast defect specific to the zero-target state of a quit habit.", "leader: quit habits at 0/day are unreadable in dark colours", "complaint", "quoted defect in the #1 app's corpus; document gives no count", "must-never-break", "high-priority", "generalisable", [], "", "the defect appears specifically when the target is zero")

c(14, "What to do, closing; 'Do not' paragraph", "dont", "Do not build a generic quit app as a second listing: 'It would compete with your own app for the same keywords, cap out around 19k ratings, and read as a repackage.' Three separate costs are named — keyword cannibalisation against your own listing, a hard ceiling at the incumbent's ~19k US ratings, and the reputational reading of a reskin.", "n/a", "mixed", "ceiling ~19k US ratings (Days Since); same-keyword competition with your own listing", "dont", "high-priority", "generalisable", [], "", "")

c(15, "'If you later want a second app' paragraph", "do", "If a second app is ever built it must be vertical and genuinely different — the document names a phone/social-media quit app, 'given that niche is unclaimed', and sets the bar explicitly: 'That is a different product with different content, not a reskin, so it wouldn't look like spam.' Different content, not a re-theme, is the test that separates a legitimate second listing from a spam signal.", "n/a", "mixed", "phone/social media is 2.0% of Days Since reviews and unclaimed by a large dedicated app", "research", "emerging", "generalisable", [], "avoids the App Store spam-reskin reading that a generic second quit app would attract", "conditional on the second product having its own content, not a shared codebase with a new skin")

c(16, "The bonus: keyword surface", "do", "Quit terms are a keyword surface a habit app can annex without a second listing: Days Since ranks #3 overall in the category on ranking strength and #1 in 10 rich markets 'purely on quit terms'. Adding a proper quit mode lets one listing compete for 'quit habit', 'break bad habits' and 'sobriety tracker' alongside the habit keywords, 'without splitting your ASO across two listings.'", "Days Since: #3 overall ranking strength, #1 in 10 rich markets, on quit terms alone", "mixed", "#3 overall on ranking strength; #1 in 10 rich markets", "do", "high-priority", "generalisable", [], "one listing carries both keyword sets; no second ASO or support queue", "")

save("w")
